{
  "correction_rules": [
    "Adjust forecasts downward if recent history shows persistent overestimation (especially after spikes).",
    "Reduce forecast magnitude by 5-10% if sentiment is neutral or slightly positive (0.00–0.25) to avoid overconfidence bias.",
    "Apply mean reversion correction: if forecast is >15% above recent 7-day average, reduce by 10–15%.",
    "Avoid overshoot after sharp upward spikes: cap forecast at 10% below the immediate prior peak if sentiment is flat or negative.",
    "For horizon >14 days, reduce forecast volatility by smoothing with 3-day moving average of true values.",
    "If sentiment >0.25, slightly increase forecast to reflect bullish momentum, but cap at 5% above recent 5-day high."
  ]
}
